  1→/**
  2→ * tools.cli.ts — thin CLI dispatcher for Prism query tools
  3→ *
  4→ * Usage (from web/ directory):
  5→ *   node --import tsx server/prism/tools.cli.ts <toolName> '<jsonArgs>'
  6→ *
  7→ * toolName: queryMarkers | scanMetricOverFrames | getFrameCallTree |
  8→ *           getThreadTimeline | correlateFrameSets |
  9→ *           scanPeakMarkers | queryFrameCounters | aggregateSubtree |
 10→ *           drillDownMarker | getSourceForSymbol |
 11→ *           querySchedState | queryAtraceSlices | queryFrameTimeline |
 12→ *           queryCpuFreq | getPerfettoCallTree | correlateFrameSchedCpu |
 13→ *           queryCallTreeSubtree | querySliceDeltas | queryOffCpuAttribution |
 14→ *           queryGcAllocByModule |
 15→ *           queryMarkersMultiState | queryFrameSummaryMultiState |
 16→ *           queryThreadsMultiState | queryAggCallTreeMultiState |
 17→ *           queryUnityMarkers
 18→ *
 19→ * SINGLE mode:
 20→ *   node --import tsx server/prism/tools.cli.ts single '{"tool":"querySchedState","args":{"role":"cur"}}'
 21→ *
 22→ * BATCH mode (amortizes tsx cold-start across many queries — MUCH faster):
 23→ *   node --import tsx server/prism/tools.cli.ts batch '[{"tool":"queryMarkers","args":{...}}, ...]'
 24→ *   → returns a JSON array of { tool, args, ok, data|error } in the same order.
 25→ *
 26→ * runId defaults to 'unity-outside-stressmove' if not provided in jsonArgs.
 27→ */
 28→
 29→import { openPrismDb } from './db.js';
 30→import {
 31→  queryMarkers,
 32→  scanMetricOverFrames,
 33→  getFrameCallTree,
 34→  getThreadTimeline,
 35→  correlateFrameSets,
 36→  scanPeakMarkers,
 37→  queryFrameCounters,
 38→  aggregateSubtree,
 39→  drillDownMarker,
 40→  getSourceForSymbol,
 41→  querySchedState,
 42→  queryAtraceSlices,
 43→  queryFrameTimeline,
 44→  queryCpuFreq,
 45→  getPerfettoCallTree,
 46→  correlateFrameSchedCpu,
 47→  queryCallTreeSubtree,
 48→  querySliceDeltas,
 49→  queryOffCpuAttribution,
 50→  queryGcAllocByModule,
 51→  queryMarkersMultiState,
 52→  queryFrameSummaryMultiState,
 53→  queryThreadsMultiState,
 54→  queryAggCallTreeMultiState,
 55→  queryUnityMarkers,
 56→} from './tools.js';
 57→import type Database from 'better-sqlite3';
 58→
 59→const DEFAULT_RUN_ID = 'unity-outside-stressmove';
 60→
 61→const PERFETTO_JSON_TOOL_NAMES = new Set([
 62→  'querySchedState',
 63→  'queryAtraceSlices',
 64→  'queryFrameTimeline',
 65→  'queryCpuFreq',
 66→  'getPerfettoCallTree',
 67→  'correlateFrameSchedCpu',
 68→  'queryCallTreeSubtree',
 69→  'querySliceDeltas',
 70→  'queryOffCpuAttribution',
 71→  'queryGcAllocByModule',
 72→]);
 73→
 74→// WT-044: Unity 多态/单态 JSON 工具集（不需要 sqlite，从 preprocess-result.json 读）
 75→const UNITY_JSON_TOOL_NAMES = new Set([
 76→  'queryMarkersMultiState',
 77→  'queryFrameSummaryMultiState',
 78→  'queryThreadsMultiState',
 79→  'queryAggCallTreeMultiState',
 80→  'queryUnityMarkers',
 81→]);
 82→
 83→type ToolRunner = (db: Database.Database | null, args: Record<string, unknown>) => unknown;
 84→
 85→const TOOLS: Record<string, ToolRunner> = {
 86→  queryMarkers:          (db, a) => queryMarkers(db!, a as unknown as Parameters<typeof queryMarkers>[1]),
 87→  scanMetricOverFrames:  (db, a) => scanMetricOverFrames(db!, a as unknown as Parameters<typeof scanMetricOverFrames>[1]),
 88→  getFrameCallTree:      (db, a) => getFrameCallTree(db!, a as unknown as Parameters<typeof getFrameCallTree>[1]),
 89→  getThreadTimeline:     (db, a) => getThreadTimeline(db!, a as unknown as Parameters<typeof getThreadTimeline>[1]),
 90→  correlateFrameSets:    (db, a) => correlateFrameSets(db!, a as unknown as Parameters<typeof correlateFrameSets>[1]),
 91→  scanPeakMarkers:       (db, a) => scanPeakMarkers(db!, a as unknown as Parameters<typeof scanPeakMarkers>[1]),
 92→  queryFrameCounters:    (db, a) => queryFrameCounters(db!, a as unknown as Parameters<typeof queryFrameCounters>[1]),
 93→  aggregateSubtree:      (db, a) => aggregateSubtree(db!, a as unknown as Parameters<typeof aggregateSubtree>[1]),
 94→  drillDownMarker:       (db, a) => drillDownMarker(db!, a as unknown as Parameters<typeof drillDownMarker>[1]),
 95→  getSourceForSymbol:    (db, a) => getSourceForSymbol(db!, a as unknown as Parameters<typeof getSourceForSymbol>[1]),
 96→  querySchedState:       (db, a) => querySchedState(db, a as unknown as Parameters<typeof querySchedState>[1]),
 97→  queryAtraceSlices:     (db, a) => queryAtraceSlices(db, a as unknown as Parameters<typeof queryAtraceSlices>[1]),
 98→  queryFrameTimeline:    (db, a) => queryFrameTimeline(db, a as unknown as Parameters<typeof queryFrameTimeline>[1]),
 99→  queryCpuFreq:          (db, a) => queryCpuFreq(db, a as unknown as Parameters<typeof queryCpuFreq>[1]),
100→  getPerfettoCallTree:   (db, a) => getPerfettoCallTree(db, a as unknown as Parameters<typeof getPerfettoCallTree>[1]),
101→  correlateFrameSchedCpu:(db, a) => correlateFrameSchedCpu(db, a as unknown as Parameters<typeof correlateFrameSchedCpu>[1]),
102→  queryCallTreeSubtree:  (db, a) => queryCallTreeSubtree(db, a as unknown as Parameters<typeof queryCallTreeSubtree>[1]),
103→  querySliceDeltas:      (db, a) => querySliceDeltas(db, a as unknown as Parameters<typeof querySliceDeltas>[1]),
104→  queryOffCpuAttribution:(db, a) => queryOffCpuAttribution(db, a as unknown as Parameters<typeof queryOffCpuAttribution>[1]),
105→  queryGcAllocByModule:  (db, a) => queryGcAllocByModule(db, a as unknown as Parameters<typeof queryGcAllocByModule>[1]),
106→  queryMarkersMultiState:      (db, a) => queryMarkersMultiState(db, a as unknown as Parameters<typeof queryMarkersMultiState>[1]),
107→  queryFrameSummaryMultiState:(db, a) => queryFrameSummaryMultiState(db, a as unknown as Parameters<typeof queryFrameSummaryMultiState>[1]),
108→  queryThreadsMultiState:      (db, a) => queryThreadsMultiState(db, a as unknown as Parameters<typeof queryThreadsMultiState>[1]),
109→  queryAggCallTreeMultiState:  (db, a) => queryAggCallTreeMultiState(db, a as unknown as Parameters<typeof queryAggCallTreeMultiState>[1]),
110→  queryUnityMarkers:           (db, a) => queryUnityMarkers(db, a as unknown as Parameters<typeof queryUnityMarkers>[1]),
111→};
112→
113→function usage(): never {
114→  console.error(
115→    'Usage: node --import tsx server/prism/tools.cli.ts <toolName> \'<jsonArgs>\'\n' +
116→    'Tools: ' + Object.keys(TOOLS).join(', ') + '\n' +
117→    'runId defaults to "' + DEFAULT_RUN_ID + '" if not specified in args.'
118→  );
119→  process.exit(1);
120→}
121→
122→const [, , toolName, rawArgs] = process.argv;
123→
124→if (!toolName || (toolName !== 'single' && toolName !== 'batch' && !TOOLS[toolName])) {
125→  console.error(`Unknown tool: ${toolName ?? '(none)'}`);
126→  usage();
127→}
128→
129→function toolNeedsDb(name: string): boolean {
130→  // perfetto JSON 工具 + unity 多态/单态 JSON 工具都不需要 sqlite
131→  return !PERFETTO_JSON_TOOL_NAMES.has(name) && !UNITY_JSON_TOOL_NAMES.has(name);
132→}
133→
134→function injectDefaultRunId(name: string, args: Record<string, unknown>): void {
135→  // WT-044: unity 多态工具默认 runId = udiff_1782983710451_be175ef1（VG 样本）
136→  if (UNITY_JSON_TOOL_NAMES.has(name)) {
137→    if (!args.runId) args.runId = 'udiff_1782983710451_be175ef1';
138→    return;
139→  }
140→  if (toolNeedsDb(name) && !args.runId) args.runId = DEFAULT_RUN_ID;
141→}
142→
143→// ── SINGLE mode: JSON envelope { tool, args } ───────────────────────
144→if (toolName === 'single') {
145→  let item: { tool?: string; args?: Record<string, unknown> };
146→  try {
147→    item = rawArgs ? JSON.parse(rawArgs) : {};
148→  } catch {
149→    console.error('Failed to parse single args as JSON object:', rawArgs);
150→    process.exit(1);
151→  }
152→  const t = item.tool;
153→  const a: Record<string, unknown> = { ...(item.args ?? {}) };
154→  if (!t || !TOOLS[t]) {
155→    console.error(`Unknown tool: ${t ?? '(none)'}`);
156→    process.exit(1);
157→  }
158→  injectDefaultRunId(t, a);
159→  const db = toolNeedsDb(t) ? openPrismDb() : null;
160→  try {
161→    const result = TOOLS[t](db, a);
162→    console.log(JSON.stringify(result, null, 2));
163→  } catch (err) {
164→    console.error('Tool error:', err instanceof Error ? err.message : String(err));
165→    process.exit(1);
166→  } finally {
167→    db?.close();
168→  }
169→  process.exit(0);
170→}
171→
172→// ── BATCH mode: run many queries in one process (amortize tsx cold-start) ──
173→if (toolName === 'batch') {
174→  let batch: Array<{ tool: string; args?: Record<string, unknown> }>;
175→  try {
176→    batch = rawArgs ? JSON.parse(rawArgs) : [];
177→  } catch {
178→    console.error('Failed to parse batch args as JSON array:', rawArgs);
179→    process.exit(1);
180→  }
181→  if (!Array.isArray(batch)) {
182→    console.error('batch expects a JSON array of { tool, args }');
183→    process.exit(1);
184→  }
185→  const needsDb = batch.some(item => item?.tool && TOOLS[item.tool] && toolNeedsDb(item.tool));
186→  const db = needsDb ? openPrismDb() : null;
187→  const results: unknown[] = [];
188→  try {
189→    for (const item of batch) {
190→      const t = item?.tool;
191→      const a: Record<string, unknown> = { ...(item?.args ?? {}) };
192→      if (!t || !TOOLS[t]) {
193→        results.push({ tool: t ?? '(none)', args: a, ok: false, error: `Unknown tool: ${t ?? '(none)'}` });
194→        continue;
195→      }
196→      injectDefaultRunId(t, a);
197→      try {
198→        const out = TOOLS[t](toolNeedsDb(t) ? db : null, a) as { data?: unknown };
199→        // tools return { data, provenance }; surface data + keep provenance
200→        results.push({ tool: t, args: a, ok: true, result: out });
201→      } catch (err) {
202→        results.push({ tool: t, args: a, ok: false, error: err instanceof Error ? err.message : String(err) });
203→      }
204→    }
205→    console.log(JSON.stringify(results, null, 2));
206→  } finally {
207→    db?.close();
208→  }
209→  process.exit(0);
210→}
211→
212→let args: Record<string, unknown>;
213→try {
214→  args = rawArgs ? JSON.parse(rawArgs) : {};
215→} catch {
216→  console.error('Failed to parse args as JSON:', rawArgs);
217→  process.exit(1);
218→}
219→
220→injectDefaultRunId(toolName, args);
221→
222→const db = toolNeedsDb(toolName) ? openPrismDb() : null;
223→try {
224→  const result = TOOLS[toolName](db, args);
225→  console.log(JSON.stringify(result, null, 2));
226→} catch (err) {
227→  console.error('Tool error:', err instanceof Error ? err.message : String(err));
228→  process.exit(1);
229→} finally {
230→  db?.close();
231→}
